import { APP_EXTENSIONS } from "@/features/extensions/registry";
import { useEditor } from "@/features/notes/editor/hooks/editor-context";
import { cn } from "@/shared/lib/utils";
import {
  SETTINGS_SECTIONS,
  type SettingsSection,
  type SettingsSectionId,
} from "../../lib/sections";
import { SettingsGeneralSection } from "./general-section";
import { SettingsProfileSection } from "./profile-section";
import { SettingsImportSection } from "./import-section";
import { SettingsSyncSection } from "./sync-section";
import { SettingsAppearanceSection } from "./appearance-section";
import { SettingsRecordingsSection } from "./recordings-section";
import { SettingsTranscriptionSection } from "./transcription-section";
import { SettingsUpdatesSection } from "./updates-section";
import { SettingsSecuritySection } from "./security-section";

const shouldIgnorePaneFocusClick = (target: EventTarget | null) => {
  if (!(target instanceof HTMLElement)) {
    return false;
  }
  return Boolean(
    target.closest("input, textarea, select, button, a, label, [contenteditable='true']")
  );
};

function SettingsRow({
  section,
  isSelected,
  onSelect,
}: {
  section: SettingsSection;
  isSelected: boolean;
  onSelect: () => void;
}) {
  return (
    <button
      type="button"
      className={cn(
        "settings-nav-row",
        isSelected && "is-selected",
      )}
      onClick={onSelect}
    >
      {section.title}
    </button>
  );
}

function SettingsDetail({
  sectionId,
  onOpenTrash,
}: {
  sectionId: SettingsSectionId;
  onOpenTrash: () => void;
}) {
  if (sectionId === "general") return <SettingsGeneralSection onOpenTrash={onOpenTrash} />;
  if (sectionId === "profile") return <SettingsProfileSection />;
  if (sectionId === "import") return <SettingsImportSection />;
  if (sectionId === "sync") return <SettingsSyncSection />;
  if (sectionId === "updates") return <SettingsUpdatesSection />;
  if (sectionId === "appearance") return <SettingsAppearanceSection />;
  if (sectionId === "transcription") return <SettingsTranscriptionSection />;
  if (sectionId === "recordings") return <SettingsRecordingsSection />;
  if (sectionId === "security" && APP_EXTENSIONS.security) return <SettingsSecuritySection />;
  return null;
}

export function SettingsMiddlePane({
  activeSection,
  onSectionChange,
  middlePaneRef,
  onPaneClick,
}: {
  activeSection: string;
  onSectionChange: (id: SettingsSectionId) => void;
  middlePaneRef: React.RefObject<HTMLDivElement | null>;
  onPaneClick: () => void;
}) {
  return (
    <div className="pane settings-nav-pane h-full min-h-0 min-w-0">
      <div className="pane-drag-region" data-tauri-drag-region aria-hidden />
      <div
        className="pane-body settings-nav-body"
        ref={middlePaneRef}
        tabIndex={0}
        onClick={(event) => {
          if (shouldIgnorePaneFocusClick(event.target)) {
            return;
          }
          onPaneClick();
        }}
      >
        <nav className="settings-nav-list" aria-label="Settings sections">
          {SETTINGS_SECTIONS.map((section) => (
            <SettingsRow
              key={section.id}
              section={section}
              isSelected={activeSection === section.id}
              onSelect={() => onSectionChange(section.id)}
            />
          ))}
        </nav>
      </div>
    </div>
  );
}

export function SettingsDetailPane({
  activeSection,
  onOpenTrash,
  onPaneClick,
}: {
  activeSection: string;
  onOpenTrash: () => void;
  onPaneClick: () => void;
}) {
  const { rightPaneRef } = useEditor();

  return (
    <div className="pane settings-detail-pane h-full min-h-0 min-w-0 dark:backdrop-blur-none">
      <div
        className="pane-body settings-detail-body"
        ref={rightPaneRef}
        tabIndex={0}
        onClick={(event) => {
          if (shouldIgnorePaneFocusClick(event.target)) {
            return;
          }
          onPaneClick();
        }}
      >
        <div className="mx-auto grid pb-1.5 max-w-[860px] max-[1320px]:max-w-full">
          <SettingsDetail
            sectionId={activeSection as SettingsSectionId}
            onOpenTrash={onOpenTrash}
          />
        </div>
      </div>
    </div>
  );
}
import { useEffect, type ReactNode } from "react";
import { create } from "zustand";

import { applyThemeToDocument } from "@/app/launch-screen";
import {
  DEFAULT_EDITOR_FONT_SIZE,
  MAX_EDITOR_FONT_SIZE,
  MIN_EDITOR_FONT_SIZE,
} from "@/shared/constants";
import {
  getInitialEditorFontSize,
  getInitialHideArchivedFeedNotes,
  getInitialNotesListMode,
  getInitialTheme,
} from "@/shared/lib/storage";
import type { NotesListMode, ThemeMode } from "@typenotes/shared/types";

type AppearanceState = {
  theme: ThemeMode;
  notesListMode: NotesListMode;
  hideArchivedFeedNotes: boolean;
  editorFontSize: number;
  setTheme: (theme: ThemeMode) => void;
  setNotesListMode: (mode: NotesListMode) => void;
  setHideArchivedFeedNotes: (hidden: boolean) => void;
  setEditorFontSize: (size: number) => void;
  increaseEditorFontSize: () => void;
  decreaseEditorFontSize: () => void;
  resetEditorFontSize: () => void;
};

export const useAppearance = create<AppearanceState>((set) => ({
  theme: getInitialTheme(),
  notesListMode: getInitialNotesListMode(),
  hideArchivedFeedNotes: getInitialHideArchivedFeedNotes(),
  editorFontSize: getInitialEditorFontSize(),
  setTheme: (theme) => set({ theme }),
  setNotesListMode: (notesListMode) => set({ notesListMode }),
  setHideArchivedFeedNotes: (hideArchivedFeedNotes) => set({ hideArchivedFeedNotes }),
  setEditorFontSize: (editorFontSize) =>
    set({
      editorFontSize: Math.min(
        MAX_EDITOR_FONT_SIZE,
        Math.max(MIN_EDITOR_FONT_SIZE, editorFontSize)
      ),
    }),
  increaseEditorFontSize: () =>
    set((state) => ({
      editorFontSize: Math.min(MAX_EDITOR_FONT_SIZE, state.editorFontSize + 1),
    })),
  decreaseEditorFontSize: () =>
    set((state) => ({
      editorFontSize: Math.max(MIN_EDITOR_FONT_SIZE, state.editorFontSize - 1),
    })),
  resetEditorFontSize: () => set({ editorFontSize: DEFAULT_EDITOR_FONT_SIZE }),
}));

export function AppearanceProvider({ children }: { children: ReactNode }) {
  useEffect(() => {
    const persist = (state: AppearanceState, previous?: AppearanceState) => {
      if (!previous || state.theme !== previous.theme) {
        window.localStorage.setItem("notes-viewer-theme", state.theme);
        applyThemeToDocument(state.theme);
      }
      if (!previous || state.notesListMode !== previous.notesListMode) {
        window.localStorage.setItem(
          "notes-viewer-notes-list-mode",
          state.notesListMode
        );
      }
      if (!previous || state.hideArchivedFeedNotes !== previous.hideArchivedFeedNotes) {
        window.localStorage.setItem(
          "notes-viewer-hide-archived-feed-notes",
          String(state.hideArchivedFeedNotes)
        );
      }
      if (!previous || state.editorFontSize !== previous.editorFontSize) {
        window.localStorage.setItem(
          "notes-viewer-editor-font-size",
          String(state.editorFontSize)
        );
      }
    };

    persist(useAppearance.getState());
    return useAppearance.subscribe(persist);
  }, []);

  return children;
}

