/* The Network-inspired desktop skin: warm paper, ink-brown type, and the
   restrained hierarchy of a personal email. Kept at the end so these rules
   form one easy-to-remove presentation layer over the existing app. */
.app {
  font-family: var(--design-font);
  letter-spacing: -0.01em;
}

.app.theme-light {
  --ui-bg: var(--design-light-bg);
  --ui-pane: var(--design-light-bg);
  --ui-border: var(--design-light-border);
  --ui-border-strong: rgba(41, 36, 33, 0.24);
  --ui-text: var(--design-light-text);
  --ui-muted: var(--design-light-muted);
  --ui-select: rgba(41, 36, 33, 0.055);
  --ui-accent: #292421;
  --background: var(--design-light-bg);
  --foreground: var(--design-light-text);
  --card: #fffdfa;
  --card-foreground: #292421;
  --popover: #fffdfa;
  --popover-foreground: #292421;
  --primary: #292421;
  --primary-foreground: #f5eee6;
  --secondary: rgba(255, 255, 255, 0.75);
  --secondary-foreground: #292421;
  --muted: rgba(255, 255, 255, 0.65);
  --muted-foreground: rgba(41, 36, 33, 0.68);
  --accent: rgba(255, 255, 255, 0.75);
  --accent-foreground: #292421;
  --border: rgba(41, 36, 33, 0.1);
  --input: rgba(41, 36, 33, 0.12);
  --ring: rgba(41, 36, 33, 0.22);
  --sidebar: #fafafa;
  --sidebar-foreground: #292421;
  --sidebar-accent: rgba(41, 36, 33, 0.055);
  --sidebar-accent-foreground: #292421;
  --sidebar-border: rgba(41, 36, 33, 0.1);
  background: var(--design-light-bg);
}

.app.theme-light .pane,
.app.theme-light .nav-pane,
.app.theme-light .notes-pane,
.app.theme-light .editor-pane,
.app.theme-light .notes-pane .pane-body,
.app.theme-light .editor-body {
  background: var(--design-light-bg);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

.app.theme-light .nav-pane {
  border-right-color: rgba(41, 36, 33, 0.1);
}

.app.theme-light .app-resize-handle::before,
.app.theme-light .app-resize-handle-editor::before {
  width: 1px;
  background: rgba(41, 36, 33, 0.1);
}

.app.theme-light .app-resize-handle:hover::before,
.app.theme-light .app-resize-handle-editor:hover::before {
  width: 1px;
  background: rgba(41, 36, 33, 0.22);
}

.app.theme-light .app-sidebar-header {
  padding: calc(18px + var(--left-panels-drag-height)) 14px 14px;
}

.app.theme-light .app-sidebar-header [data-sidebar="menu-item"] {
  gap: 6px;
}

.app.theme-light .app-sidebar-header [data-sidebar="menu-button"],
.app.theme-light .app-sidebar-header button,
.app.theme-light .app-sidebar-content > [data-sidebar="group"]:last-child [data-sidebar="menu-button"] {
  border: 0;
  border-radius: 999px;
  background: rgba(41, 36, 33, 0.05);
  color: rgba(41, 36, 33, 0.72);
  box-shadow: none;
}

.app.theme-light .app-sidebar-header [data-sidebar="menu-button"]:hover,
.app.theme-light .app-sidebar-header button:hover,
.app.theme-light .app-sidebar-content > [data-sidebar="group"]:last-child [data-sidebar="menu-button"]:hover {
  background: rgba(41, 36, 33, 0.09);
  color: #292421;
}

.app.theme-light .app-sidebar-content > [data-sidebar="group"]:last-child {
  padding: 12px 14px 16px;
}

.app.theme-light .pane-tabs-wrap {
  padding: 12px 14px 10px;
}

.app.theme-light .folders-tabs-list {
  gap: 18px;
}

.app.theme-light .folders-tab-trigger {
  color: rgba(41, 36, 33, 0.5);
  font-size: 12px;
  font-weight: 400;
}

.app.theme-light .folders-tab-trigger[data-state="active"] {
  color: #292421;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 0.2em;
}

.app.theme-light .sidebar-folders-section .nav-scroll-area {
  padding-inline: 8px;
}

.app.theme-light .tree-pane .item-row,
.app.theme-light .note-row {
  min-height: 34px;
  margin: 1px 4px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  box-shadow: none;
  transition: background-color 160ms cubic-bezier(0.22, 1, 0.36, 1),
    color 160ms cubic-bezier(0.22, 1, 0.36, 1);
}

.app.theme-light .tree-pane .item-row:hover,
.app.theme-light .note-row:hover {
  background: rgba(41, 36, 33, 0.035);
}

.app.theme-light .tree-pane .item-row.selected {
  border-radius: 0;
  background: var(--design-light-selection);
  box-shadow: inset 2px 0 0 var(--design-light-text);
}

.app.theme-light .note-row.selected {
  background: var(--design-light-selection);
  box-shadow: none;
}

.app.theme-light .tree-pane .item-row.selected .item-label,
.app.theme-light .note-row-title {
  font-weight: 400;
}

.app.theme-light .tree-pane .item-label,
.app.theme-light .note-row-title {
  color: #292421;
  font-size: 13px;
}

.app.theme-light .tree-pane .folder-glyph,
.app.theme-light .tree-pane .nav-note-glyph,
.app.theme-light .tree-pane .nav-note-recording-icon,
.app.theme-light .note-row-recording-icon {
  color: rgba(41, 36, 33, 0.5);
}

.app.theme-light .tree-pane .note-count,
.app.theme-light .note-row-date,
.app.theme-light .note-row-snippet {
  color: rgba(41, 36, 33, 0.55);
  font-weight: 400;
}

.app.theme-light .notes-pane .pane-body {
  padding: calc(12px + var(--left-panels-drag-height)) 8px 12px;
}

.app.theme-light .note-row {
  padding: 9px 10px;
}

.app.theme-light .note-row-subline {
  margin-top: 3px;
}

.editor-top-row {
  min-height: calc(12px + var(--left-panels-drag-height));
  padding: calc(8px + var(--left-panels-drag-height)) clamp(22px, 5vw, 64px) 0;
  align-items: flex-start;
}

.editor-lens-menu-area {
  margin-left: auto;
}

.app.theme-light .editor-lens-menu-trigger {
  border: 0;
  border-radius: 999px;
  background: rgba(41, 36, 33, 0.05);
  color: rgba(41, 36, 33, 0.62);
}

.app.theme-light .editor-lens-menu-trigger:hover {
  border: 0;
  background: rgba(41, 36, 33, 0.09);
  color: #292421;
}

.app.theme-light .tiptap-content {
  width: min(100%, calc(40rem + clamp(44px, 10vw, 128px)));
  margin: 0;
  padding: 14px clamp(22px, 5vw, 64px) 16px;
  color: var(--design-light-text);
  font-family: var(--design-font);
  font-size: clamp(var(--editor-font-size, 14px), 1.1vw, 16px);
  line-height: 1.52;
}

.app.theme-light .tiptap-content p.is-editor-empty:first-child::before {
  color: rgba(41, 36, 33, 0.45);
  font-family: var(--design-font);
}

.app.theme-light .tiptap-content blockquote {
  border-left-color: rgba(41, 36, 33, 0.2);
  color: rgba(41, 36, 33, 0.68);
}

.app.theme-light .tiptap-content code,
.app.theme-light .tiptap-content pre {
  background: rgba(41, 36, 33, 0.06);
}

.app.sidebar-collapsed .editor-top-row {
  padding-inline: clamp(56px, 20vw, 380px) clamp(22px, 5vw, 64px);
}

.app.sidebar-collapsed.theme-light .tiptap-content {
  width: 100%;
  max-width: none;
  padding-left: clamp(56px, 20vw, 380px);
  padding-right: clamp(56px, 20vw, 380px);
}

.app.theme-dark {
  --ui-bg: var(--design-dark-bg);
  --ui-pane: var(--design-dark-bg);
  --ui-border: var(--design-dark-border);
  --ui-border-strong: rgba(255, 255, 255, 0.18);
  --ui-text: var(--design-dark-text);
  --ui-muted: var(--design-dark-muted);
  --ui-select: rgba(255, 255, 255, 0.075);
  --ui-accent: oklch(82% 0.006 67.8);
  background: var(--design-dark-bg);
}

.app.theme-dark .pane,
.app.theme-dark .nav-pane,
.app.theme-dark .notes-pane,
.app.theme-dark .editor-pane,
.app.theme-dark .notes-pane .pane-body,
.app.theme-dark .editor-body,
.app.theme-dark .tiptap-editor {
  background: var(--design-dark-bg);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

.app.theme-dark .nav-pane {
  border-right-color: rgba(255, 255, 255, 0.1);
}

.app.theme-dark .tree-pane .item-row,
.app.theme-dark .note-row {
  margin: 1px 4px;
  border-radius: 7px;
}

.app.theme-dark .tree-pane .item-row.selected {
  border-radius: 0;
  background: var(--design-dark-selection);
  box-shadow: inset 2px 0 0 var(--design-dark-text);
}

.app.theme-dark .note-row.selected {
  background: var(--design-dark-selection);
  box-shadow: none;
}

.app.theme-dark .tiptap-content {
  padding: 14px clamp(22px, 5vw, 64px) 16px;
  font-family: var(--design-font);
  font-size: clamp(var(--editor-font-size, 14px), 1.1vw, 16px);
  line-height: 1.52;
}

@media (max-width: 760px) {
  .editor-top-row {
    padding: 8px 18px 0;
  }

  .app.theme-light .tiptap-content,
  .app.theme-dark .tiptap-content {
    padding-inline: 18px;
  }
}

