          </ResizablePanel>
          <ResizableHandle className="app-resize-handle" />
          <ResizablePanel
            id="middle"
            defaultSize="25%"
            minSize="18%"
            maxSize="40%"
            className="min-w-0 h-full min-h-0"
          >
            {middlePane}
          </ResizablePanel>
          <ResizableHandle className="app-resize-handle app-resize-handle-editor" />
          <ResizablePanel
            id="content"
            defaultSize="53%"
            minSize="30%"
            className="min-w-0 h-full min-h-0"
          >
            {rightPane}
          </ResizablePanel>
        </ResizablePanelGroup>
      )}
    </div>
  );
}

