/* Global app styling for the desktop and mobile shells. */
@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

@custom-variant dark (&:is(.dark *));

:root {
  /* DESIGN ATOMS — edit these values to retheme the desktop UI. */
  --design-font: "Helvetica Neue", Helvetica, Arial, sans-serif;
  --design-light-bg: #fafafa;
  --design-light-text: #292421;
  --design-light-muted: rgba(41, 36, 33, 0.62);
  --design-light-border: rgba(41, 36, 33, 0.1);
  --design-light-selection: rgba(41, 36, 33, 0.065);
  --design-dark-bg: #0b0a09;
  --design-dark-text: oklch(82% 0.006 67.8);
  --design-dark-muted: oklch(57% 0.008 67.8);
  --design-dark-border: rgba(255, 255, 255, 0.1);
  --design-dark-selection: rgba(255, 255, 255, 0.075);

  font-family: "Avenir Next", "SF Pro Text", "Segoe UI", "Noto Sans", Arial, sans-serif;
  font-size: 14px;
  line-height: 1.35;
  color: #101418;
  background-color: #ffffff;
  --titlebar-height: 40px;
  --left-panels-drag-height: 28px;
  --ui-bg: #ffffff;
  --ui-pane: #ffffff;
  --ui-border: #d3d9df;
  --ui-border-strong: #9ba6b1;
  --ui-text: #101418;
  --ui-muted: #66717c;
  --ui-select: #f2f5f7;
  --ui-accent: #1f6feb;
  --radius: 0.625rem;
  --background: oklch(1 0 0);
  --foreground: oklch(0.141 0.005 285.823);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.141 0.005 285.823);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.141 0.005 285.823);
  --primary: oklch(0.21 0.006 285.885);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.967 0.001 286.375);
  --secondary-foreground: oklch(0.21 0.006 285.885);
  --muted: oklch(0.967 0.001 286.375);
  --muted-foreground: oklch(0.552 0.016 285.938);
  --accent: oklch(0.967 0.001 286.375);
  --accent-foreground: oklch(0.21 0.006 285.885);
  --destructive: oklch(0.577 0.245 27.325);
  --border: oklch(0.92 0.004 286.32);
  --input: oklch(0.92 0.004 286.32);
  --ring: oklch(0.705 0.015 286.067);
      sidebarCollapsed,
      setSidebarCollapsed,
      deleteSelectedNotes: deleteSelectedNotesByShortcut,
      // The lock shortcut is optional. When security is disabled, keep the
